package com.lolfm.simulator;import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class LateGamePhaseTest{
 @Test void timeTransitionOccursAfter1800TickAndSchedulesPlus30(){GameState s=LateGameTestSupport.state();LateGameTestSupport.midGameAt(s,1799);LateGameMacroResolver r=new LateGameMacroResolver();assertTrue(r.transitionIfDue(s,new MidGameMacroResolver()).isEmpty());s.advanceTimeSeconds(1);assertTrue(r.transitionIfDue(s,new MidGameMacroResolver()).isPresent());assertEquals(MatchPhase.LATE_GAME,s.getLanePhaseState().getMatchPhase());assertEquals(LateGameTransitionReason.TIME_LIMIT,s.getLateGameState().getTransitionReason());assertEquals(1830,s.getLateGameState().getNextEvaluationAtSeconds());assertFalse(s.getLateGameState().due(1800));}
 @Test void inhibitorTowerCausesEarlyTransitionButLaningCannotSkipMidGame(){GameState s=LateGameTestSupport.state();LateGameTestSupport.destroyThroughInhibitorTower(s,TeamSide.RED,Lane.MID);LateGameMacroResolver r=new LateGameMacroResolver();assertTrue(r.transitionIfDue(s,new MidGameMacroResolver()).isEmpty());LateGameTestSupport.midGameAt(s,800);assertTrue(r.transitionIfDue(s,new MidGameMacroResolver()).isPresent());assertEquals(LateGameTransitionReason.INHIBITOR_TOWER_DESTROYED,s.getLateGameState().getTransitionReason());assertEquals(s.getCurrentTimeSeconds()+30,s.getLateGameState().getNextEvaluationAtSeconds());assertTrue(r.transitionIfDue(s,new MidGameMacroResolver()).isEmpty());}
}
